-- Login sessions and their refresh tokens.
--
-- Every successful login is one session. A session has a chain of refresh tokens: each refresh rotates the current
-- one (it gets "rotatedOn") and adds the next, so exactly one token per session is current. Only the SHA-256 of a
-- token is stored: the token itself is 256 random bits and lives only in the browser's HttpOnly cookie, so a copy of
-- this table gives nobody a usable token.

CREATE TABLE authsession_tbl
(
    "pId"               BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "userId"            BIGINT      NOT NULL REFERENCES user_tbl ("pId"),
    -- Set at creation from the user's roles and never changed: PANEL sessions (any staff role) are much shorter.
    kind                VARCHAR(10) NOT NULL CHECK (kind IN ('CUSTOMER', 'PANEL')),
    "createdOn"         TIMESTAMPTZ NOT NULL,
    "lastUsedOn"        TIMESTAMPTZ NOT NULL,
    -- Moves forward with every refresh, never past the absolute end.
    "idleExpiresOn"     TIMESTAMPTZ NOT NULL,
    "absoluteExpiresOn" TIMESTAMPTZ NOT NULL,
    "revokedOn"         TIMESTAMPTZ,
    "revokeReason"      VARCHAR(20) CHECK ("revokeReason" IN
                                           ('LOGOUT', 'LOGOUT_ALL', 'REUSE_DETECTED', 'PHONE_CHANGED', 'ROLES_CHANGED',
                                            'ACCOUNT_DELETED')),
    -- For showing the sessions to their owner one day; never used for security.
    "deviceName"        VARCHAR(100),
    "userAgent"         VARCHAR(255),
    "createdIp"         VARCHAR(45),
    CHECK ("lastUsedOn" >= "createdOn"),
    CHECK ("absoluteExpiresOn" > "createdOn"),
    CHECK ("idleExpiresOn" <= "absoluteExpiresOn"),
    CHECK (("revokedOn" IS NULL) = ("revokeReason" IS NULL))
);

-- "Log out everywhere" and revoking on a role or phone change look for a user's live sessions.
CREATE INDEX authsession_user_live_idx ON authsession_tbl ("userId") WHERE "revokedOn" IS NULL;

CREATE TABLE refreshtoken_tbl
(
    "pId"       BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "sessionId" BIGINT      NOT NULL REFERENCES authsession_tbl ("pId"),
    "tokenHash" BYTEA       NOT NULL UNIQUE CHECK (length("tokenHash") = 32),
    "createdOn" TIMESTAMPTZ NOT NULL,
    "rotatedOn" TIMESTAMPTZ CHECK ("rotatedOn" >= "createdOn")
);

-- Exactly one current token per session.
CREATE UNIQUE INDEX refreshtoken_one_current_idx ON refreshtoken_tbl ("sessionId") WHERE "rotatedOn" IS NULL;
